"""
Neatlogs Semantic Conventions - Attribute Mapper

This module provides utilities to map vendor-specific attributes unified neatlogs.* namespace.
"""

import json
import re
from pathlib import Path
from typing import Any, Dict, Optional


class AttributeMapper:
    """
    Maps vendor-specific semantic convention attributes to Neatlogs namespace.
    """

    def __init__(self, config_path: Optional[str] = None):
        """
        Initialize the attribute mapper.

        Args:
            config_path: Path to attribute-mapping.json. If None, uses default location.
        """
        if config_path is None:
            config_path = str(Path(__file__).parent / "attribute-mapping.json")

        with open(config_path, "r") as f:
            self.config = json.load(f)

        self.mappings = self.config.get("mappings", {})
        self.keep_as_is = set(self.config.get("keep_as_is", {}).get("attributes", []))
        self.ignore_patterns = self.config.get("ignore", {}).get("patterns", [])

    def should_ignore(self, attr_name: str) -> bool:
        """Check if an attribute should be ignored."""
        for pattern in self.ignore_patterns:
            if re.match(pattern.replace("*", ".*"), attr_name):
                return True
        return False

    def should_keep_as_is(self, attr_name: str) -> bool:
        """Check if an attribute should be kept unchanged (OTEL standard)."""
        return attr_name in self.keep_as_is

    def map_span_kind(self, attributes: Dict[str, Any]) -> str:
        """
        Extract and normalize span kind from multiple possible sources.
        If no explicit span kind is found, infer from attribute patterns.
        """
        span_kind_config = self.mappings.get("span_kind", {})
        sources = span_kind_config.get("sources", [])
        values_map = span_kind_config.get("values", {})
        priority = span_kind_config.get("priority", "openinference")

        span_kind_value = None

        if priority == "openinference":
            if "openinference.span.kind" in attributes:
                span_kind_value = attributes["openinference.span.kind"]
        else:
            for source in sources:
                if source in attributes:
                    span_kind_value = attributes[source]
                    break

        if span_kind_value and span_kind_value in values_map:
            return values_map[span_kind_value]

        is_llm_span = any(
            [
                "llm.model_name" in attributes,
                "gen_ai.request.model" in attributes,
                "llm.token_count.prompt" in attributes,
                "llm.token_count.completion" in attributes,
                "gen_ai.usage.prompt_tokens" in attributes,
                "gen_ai.usage.completion_tokens" in attributes,
            ]
        )

        if is_llm_span:
            return "llm"

        return "unknown"

    def map_simple_attribute(
        self, mapping_config: Dict[str, Any], attributes: Dict[str, Any]
    ) -> Optional[Any]:
        """
        Map a simple attribute from multiple sources to target.

        Args:
            mapping_config: Configuration for this attribute mapping
            attributes: Original attributes

        Returns:
            Value from first matching source, or None
        """
        sources = mapping_config.get("sources", [])

        for source in sources:
            if source in attributes:
                return attributes[source]

        return None

    def map_indexed_attributes(
        self,
        mapping_config: Dict[str, Any],
        attributes: Dict[str, Any],
        target_base: str,
    ) -> Dict[str, Any]:
        """
        Map indexed attributes like messages (llm.input_messages.0.role).

        Args:
            mapping_config: Configuration for this attribute mapping
            attributes: Original attributes
            target_base: Base target attribute name

        Returns:
            Dictionary of mapped indexed attributes
        """
        mapped = {}
        sources = mapping_config.get("sources", [])

        for attr_name, attr_value in attributes.items():
            for source_pattern in sources:
                regex_pattern = source_pattern.replace("{i}", r"(\d+)")
                regex_pattern = regex_pattern.replace(".", r"\.")
                match = re.match(regex_pattern, attr_name)

                if match:
                    index = match.group(1)
                    target = target_base.replace("{i}", index)
                    mapped[target] = attr_value

        return mapped

    def map_nested_config(
        self,
        config: Dict[str, Any],
        attributes: Dict[str, Any],
        span_kind: Optional[str] = None,
    ) -> Dict[str, Any]:
        """
        Recursively map nested configuration.

        Args:
            config: Configuration dictionary
            attributes: Original attributes
            span_kind: Current span kind for dynamic substitution

        Returns:
            Mapped attributes
        """
        mapped = {}

        for key, value in config.items():
            if key in ["description", "sources", "target", "indexed", "priority", "values"]:
                continue

            if isinstance(value, dict):
                if "sources" in value:
                    if value.get("indexed", False):
                        target = value.get("target", "")
                        indexed_mapped = self.map_indexed_attributes(value, attributes, target)
                        mapped.update(indexed_mapped)

                        if "target_content" in value:
                            content_target = value["target_content"]
                            content_mapped = self.map_indexed_attributes(
                                value, attributes, content_target
                            )
                            mapped.update(content_mapped)
                    else:
                        target = value.get("target", "")
                        if span_kind and "{span_kind}" in target:
                            target = target.replace("{span_kind}", span_kind)

                        result = self.map_simple_attribute(value, attributes)
                        if result is not None:
                            mapped[target] = result
                else:
                    nested_mapped = self.map_nested_config(value, attributes, span_kind)
                    mapped.update(nested_mapped)

        return mapped

    def map_attributes(
        self, attributes: Dict[str, Any], span_kind: Optional[str] = None
    ) -> Dict[str, Any]:
        """
        Map all attributes from vendor-specific to neatlogs namespace.

        Args:
            attributes: Original span attributes
            span_kind: Optional span kind override. If None, will be extracted from attributes.

        Returns:
            Mapped attributes with neatlogs.* namespace
        """
        mapped = {}

        if span_kind is None:
            span_kind = self.map_span_kind(attributes)
        mapped["neatlogs.span.kind"] = span_kind

        for section_name, section_config in self.mappings.items():
            if section_name == "span_kind":
                continue

            if isinstance(section_config, dict) and "mappings" in section_config:
                nested_mapped = self.map_nested_config(
                    section_config["mappings"], attributes, span_kind
                )
                mapped.update(nested_mapped)
            elif isinstance(section_config, dict) and "sources" in section_config:
                target = section_config.get("target", "")
                if "{span_kind}" in target:
                    target = target.replace("{span_kind}", span_kind)

                result = self.map_simple_attribute(section_config, attributes)
                if result is not None:
                    mapped[target] = result
            else:
                nested_mapped = self.map_nested_config(section_config, attributes, span_kind)
                mapped.update(nested_mapped)

        for attr_name, attr_value in attributes.items():
            if self.should_keep_as_is(attr_name) and attr_name not in mapped:
                mapped[attr_name] = attr_value

        mapped_sources = set()
        for section_config in self.mappings.values():
            if isinstance(section_config, dict):
                if "sources" in section_config:
                    mapped_sources.update(section_config.get("sources", []))
                elif "mappings" in section_config:
                    self._collect_mapped_sources(section_config["mappings"], mapped_sources)
                else:
                    self._collect_mapped_sources(section_config, mapped_sources)

        for attr_name, attr_value in attributes.items():
            if (
                attr_name not in mapped_sources
                and attr_name not in mapped
                and not self.should_ignore(attr_name)
            ):
                mapped[attr_name] = attr_value

        mapped = {k: v for k, v in mapped.items() if not self.should_ignore(k)}

        return mapped

    def _collect_mapped_sources(self, config: Dict[str, Any], collected: set) -> None:
        """
        Recursively collect all source attribute names from nested config.

        Args:
            config: Configuration dict
            collected: Set to add source attribute names to
        """
        for value in config.values():
            if isinstance(value, dict):
                if "sources" in value:
                    collected.update(value.get("sources", []))
                else:
                    self._collect_mapped_sources(value, collected)

    def get_span_kind_value_mapping(self) -> Dict[str, str]:
        """Get the span kind value mapping."""
        return self.mappings.get("span_kind", {}).get("values", {})

    def get_target_attribute_name(
        self, source_attr: str, span_kind: Optional[str] = None
    ) -> Optional[str]:
        """
        Get the target neatlogs attribute name for a source attribute.

        Args:
            source_attr: Source attribute name
            span_kind: Optional span kind for dynamic substitution

        Returns:
            Target attribute name or None if no mapping exists
        """

        def search_config(config: Dict[str, Any], target_span_kind: Optional[str]) -> Optional[str]:
            for key, value in config.items():
                if isinstance(value, dict):
                    if "sources" in value:
                        sources = value.get("sources", [])
                        if source_attr in sources:
                            target = value.get("target", "")
                            if target_span_kind and "{span_kind}" in target:
                                target = target.replace("{span_kind}", target_span_kind)
                            return target
                    result = search_config(value, target_span_kind)
                    if result:
                        return result
            return None

        return search_config(self.mappings, span_kind)


_mapper_instance: Optional[AttributeMapper] = None


def get_mapper() -> AttributeMapper:
    """Get the global AttributeMapper instance."""
    global _mapper_instance
    if _mapper_instance is None:
        _mapper_instance = AttributeMapper()
    return _mapper_instance


def map_attributes(attributes: Dict[str, Any], span_kind: Optional[str] = None) -> Dict[str, Any]:
    """
    Convenience function to map attributes using the global mapper.

    Args:
        attributes: Original span attributes
        span_kind: Optional span kind override

    Returns:
        Mapped attributes with neatlogs.* namespace
    """
    mapper = get_mapper()
    return mapper.map_attributes(attributes, span_kind)

import ast
import json
import logging
import re
from typing import Any, Dict, List, Optional
from urllib.parse import urlsplit, urlunsplit

from opentelemetry import metrics
from opentelemetry.sdk.trace import ReadableSpan
from opentelemetry.trace import SpanKind

from .instrumentation_scope_parser import enrich_with_scope_detection
from .logger import get_logger
from .span_kind import normalize_explicit_span_kind, resolve_explicit_span_kind

# Matches Python object repr strings like:
#   <function BaseTool.<lambda> at 0x110107be0>
#   <bound method Foo.bar at 0x7f...>
#   <MyClass object at 0x...>
_PYTHON_REPR_RE = re.compile(r"^<[A-Za-z_].*?\bat\s+0x[0-9a-fA-F]+>$")

# Maps neatlogs.provider values → neatlogs.llm.system
# System values are from OpenInferenceLLMSystemValues (openai/anthropic/cohere/mistralai/vertexai)
# For providers not in OI's LLMSystemValues we use the provider name as the system value.
# "aws"/"bedrock" are intentionally omitted: on Bedrock, llm.system is set to the underlying
# model vendor (e.g. "anthropic" for Claude) which is more informative than "aws".
_PROVIDER_TO_SYSTEM: Dict[str, str] = {
    "openai": "openai",
    "azure": "openai",  # Azure OpenAI uses OpenAI's system
    "azure_openai": "openai",
    "anthropic": "anthropic",
    "cohere": "cohere",
    "mistral": "mistralai",  # OI LLMSystemValues.MISTRALAI = "mistralai"
    "mistralai": "mistralai",
    "google": "google",
    "vertex_ai": "vertexai",  # OI LLMSystemValues.VERTEXAI = "vertexai"
    "groq": "groq",
    "xai": "xai",
    "deepseek": "deepseek",
}


def _is_python_repr(s: str) -> bool:
    return bool(_PYTHON_REPR_RE.match(s.strip()))


def _clean_python_reprs(obj: Any) -> Any:
    """Recursively remove Python object repr strings from a parsed JSON structure."""
    if isinstance(obj, dict):
        return {
            k: _clean_python_reprs(v)
            for k, v in obj.items()
            if not (isinstance(v, str) and _is_python_repr(v))
        }
    if isinstance(obj, list):
        return [
            _clean_python_reprs(item)
            for item in obj
            if not (isinstance(item, str) and _is_python_repr(item))
        ]
    return obj


class UnifiedAttributeProcessor:

    def __init__(
        self,
        mapping_config: Dict[str, Any],
        debug: bool = False,
    ):
        self.mapping = mapping_config
        self.debug = debug
        self.logger = get_logger()

        # Enable debug logging if debug mode is on
        if self.debug:
            self.logger.setLevel(logging.DEBUG)
            for handler in self.logger.handlers:
                handler.setLevel(logging.DEBUG)

        self.meter = metrics.get_meter("neatlogs.sdk")

    def _sanitize_io_value(self, val: Any) -> Any:
        """Remove Python object reprs from input.value / output.value JSON strings.

        Also drops the top-level "self" key that CrewAI injects when it serializes
        the entire tool instance as part of the span input.
        """
        if not isinstance(val, str):
            return val
        try:
            parsed = json.loads(val)
            cleaned = _clean_python_reprs(parsed)
            if isinstance(cleaned, dict):
                cleaned.pop("self", None)
            if cleaned != parsed:
                return json.dumps(cleaned)
        except Exception:
            pass
        return val

    def process(self, span: ReadableSpan) -> Dict[str, Any]:
        res_attrs = dict(span.resource.attributes) if span.resource else {}
        attrs = {**res_attrs, **dict(span.attributes)}

        # Add span name for downstream processing
        attrs["_span_name"] = span.name

        # Extract framework/platform/provider from instrumentation scope
        scope_name = span.instrumentation_scope.name if span.instrumentation_scope else None
        # TODO: In future, track parent spans to get parent_scope_name for better framework detection
        enrich_with_scope_detection(attrs, scope_name, parent_scope_name=None)
        if self.debug:
            trace_id = f"{span.context.trace_id:032x}" if span.context else ""
            span_id = f"{span.context.span_id:016x}" if span.context else ""
            has_crewai_attrs = any(k.startswith("crewai.") for k in attrs.keys())
            self.logger.debug(
                "[ScopeDetection] trace_id=%s span_id=%s span_name=%s scope=%s framework=%s provider=%s platform=%s has_crewai_attrs=%s",
                trace_id,
                span_id,
                span.name,
                scope_name,
                attrs.get("neatlogs.framework"),
                attrs.get("neatlogs.provider"),
                attrs.get("neatlogs.platform"),
                has_crewai_attrs,
            )

        attrs = self._normalize_conventions(span, attrs)

        computed_metrics = self._extract_operational_metrics(span, attrs)
        attrs.update(computed_metrics)

        event_attrs = self._upcycle_events(span)
        attrs.update(event_attrs)

        try:
            from ..config import enrich_invocation_parameters

            enrich_invocation_parameters(attrs, enable_enrichment=True)
        except Exception as e:
            self.logger.warning(f"Failed to enrich invocation parameters: {e}")

        unified = self._apply_namespace_mapping(attrs)
        if unified.get("neatlogs.span.kind") == "http":
            for key in ("input.value", "input.mime_type", "output.value", "output.mime_type"):
                if key in attrs:
                    unified[key] = attrs[key]
        self._add_intermediate_steps(unified)

        # 🔥 CRITICAL: Filter out massive embedding vectors before export
        # Embedding vectors can be 4MB+ (1000 embeddings × 4096 dimensions), causing:
        # - Kafka message size limits (1MB default)
        # - ClickHouse memory exhaustion (6GB+ RAM usage)
        # - Network/storage costs
        span_kind = (unified.get("neatlogs.span.kind") or "").lower()
        if span_kind in ("embedding", "vector_store"):
            unified = self._filter_embedding_vectors(unified)

        return unified

    def _normalize_conventions(self, span: ReadableSpan, attrs: Dict[str, Any]) -> Dict[str, Any]:
        if span.kind == SpanKind.CLIENT and self._looks_like_http(attrs):
            attrs["openinference.span.kind"] = "HTTP"
            self._add_http_canonical_io(attrs)

        if "openinference.span.kind" not in attrs and any(
            k.startswith("crewai.crew.") for k in attrs.keys()
        ):
            attrs["openinference.span.kind"] = "CHAIN"

        self._add_crewai_token_usage_fallback(attrs)
        self._add_reasoning_tokens_from_output_value(attrs)
        self._add_crewai_kickoff_telemetry(attrs)

        # Extract tool calls from output messages (OpenInference format)
        tool_calls: Dict[int, Dict[str, Any]] = {}
        oi_tool_re = re.compile(
            r"^llm\.output_messages\.(\d+)\.message\.tool_calls\.(\d+)\.tool_call\.function\.(name|arguments)$"
        )
        oi_tool_id_re = re.compile(
            r"^llm\.output_messages\.(\d+)\.message\.tool_calls\.(\d+)\.tool_call\.id$"
        )

        keys_to_remove: List[str] = []
        for k, v in list(attrs.items()):
            # OpenInference tool call function (name, arguments)
            m = oi_tool_re.match(k)
            if m:
                _msg_idx, call_idx, field = m.groups()
                idx = int(call_idx)
                tool_calls.setdefault(idx, {})[field] = v
                keys_to_remove.append(k)
                continue

            # OpenInference tool call id (separate pattern)
            m = oi_tool_id_re.match(k)
            if m:
                _msg_idx, call_idx = m.groups()
                idx = int(call_idx)
                tool_calls.setdefault(idx, {})["id"] = v
                keys_to_remove.append(k)
                continue

        for idx in sorted(tool_calls.keys()):
            tc = tool_calls[idx]
            if "id" in tc:
                attrs[f"llm.tool_calls.{idx}.id"] = tc["id"]
            if "name" in tc:
                attrs[f"llm.tool_calls.{idx}.name"] = tc["name"]
            if "arguments" in tc:
                attrs[f"llm.tool_calls.{idx}.arguments"] = tc["arguments"]

        for k in keys_to_remove:
            attrs.pop(k, None)

        # Extract tool_call_id and name from input messages (tool response messages)
        input_msg_tool_re = re.compile(
            r"^llm\.input_messages\.(\d+)\.message\.(tool_call_id|name)$"
        )
        for k, v in list(attrs.items()):
            m = input_msg_tool_re.match(k)
            if m:
                msg_idx, field = m.groups()
                # Map to new structured format
                attrs[f"llm.input_messages.{msg_idx}.{field}"] = v

        # Extract invalid_tool_calls from output (LangChain AIMessage often includes this)
        # Look for patterns like: llm.output or gen_ai.completion containing invalid_tool_calls
        llm_output = attrs.get("llm.output") or attrs.get("output.value")
        if llm_output and isinstance(llm_output, str):
            try:
                output_data = json.loads(llm_output)
                # Navigate through nested structure to find invalid_tool_calls
                if isinstance(output_data, dict):
                    # LangChain format: generations[0][0].message.invalid_tool_calls
                    generations = output_data.get("generations", [])
                    if generations and len(generations) > 0 and len(generations[0]) > 0:
                        message = generations[0][0].get("message", {})
                        invalid_calls = message.get("invalid_tool_calls", [])
                        if invalid_calls:
                            attrs["llm.invalid_tool_calls"] = json.dumps(invalid_calls)
            except (json.JSONDecodeError, TypeError, AttributeError):
                pass

        # Extract tool_call_id from tool.output (for TOOL kind spans)
        # This provides structured field that Kafka consumer currently extracts from JSON
        tool_output = attrs.get("tool.output") or attrs.get("output.value")
        if tool_output and isinstance(tool_output, str):
            try:
                output_data = json.loads(tool_output)
                if isinstance(output_data, dict):
                    tool_call_id = output_data.get("tool_call_id") or output_data.get("toolCallId")
                    if tool_call_id:
                        attrs["tool_call_id"] = tool_call_id
            except (json.JSONDecodeError, TypeError):
                pass

        tool_defs: Dict[int, Dict[str, Any]] = {}
        oi_schema_re = re.compile(r"^llm\.tools\.(\d+)\.tool\.json_schema$")
        ol_fn_re = re.compile(r"^llm\.request\.functions\.(\d+)\.(name|description|input_schema)$")

        keys_to_remove = []
        for k, v in list(attrs.items()):
            m = ol_fn_re.match(k)
            if m:
                idx_s, field = m.groups()
                idx = int(idx_s)
                tool_defs.setdefault(idx, {})[field] = v
                keys_to_remove.append(k)
                continue

            m = oi_schema_re.match(k)
            if m:
                idx = int(m.group(1))
                schema = v
                if isinstance(schema, str):
                    try:
                        schema = json.loads(schema)
                    except Exception:
                        schema = None
                if isinstance(schema, dict):
                    td = tool_defs.setdefault(idx, {})
                    td.setdefault("name", schema.get("name"))
                    td.setdefault("description", schema.get("description"))
                    td.setdefault(
                        "input_schema", schema.get("input_schema") or schema.get("parameters")
                    )
                keys_to_remove.append(k)

        for idx in sorted(tool_defs.keys()):
            td = tool_defs[idx]
            if td.get("name") is not None:
                attrs.setdefault(f"llm.tools.{idx}.name", td["name"])
            if td.get("description") is not None:
                attrs.setdefault(f"llm.tools.{idx}.description", td["description"])
            if td.get("input_schema") is not None:
                val = td["input_schema"]
                if not isinstance(val, str):
                    try:
                        val = json.dumps(val)
                    except Exception:
                        val = str(val)
                attrs.setdefault(f"llm.tools.{idx}.input_schema", val)

        for k in keys_to_remove:
            attrs.pop(k, None)

        if "openinference.span.kind" not in attrs:
            db_system = attrs.get("db.system")
            db_operation = attrs.get("db.operation", "").lower()

            if isinstance(db_system, str) and db_system.lower() in {
                "chroma",
                "chromadb",
                "pinecone",
                "qdrant",
                "milvus",
                "marqo",
                "weaviate",
                "lancedb",
                "pgvector",
                "elasticsearch",
            }:
                # Use db.operation (if available) or span name to distinguish RETRIEVER vs VECTOR_STORE
                span_name = attrs.get("_span_name", "").lower()

                # Read operations (retrieval)
                retrieval_ops = [
                    "query",
                    "search",
                    "get",
                    "fetch",
                    "find",
                    "retrieve",
                    "scroll",
                    "peek",
                    "discover",
                    "recommend",
                    "aggregate",
                    "hybrid_search",
                    "select",
                ]

                # Write operations
                write_ops = [
                    "upsert",
                    "insert",
                    "add",
                    "update",
                    "delete",
                    "create",
                    "drop",
                    "put",
                    "set",
                    "upload",
                    "index",
                ]

                # Check db.operation first (most reliable)
                is_retrieval = False
                if db_operation:
                    is_retrieval = any(op in db_operation for op in retrieval_ops)
                    is_write = any(op in db_operation for op in write_ops)
                else:
                    # Fallback to span name
                    is_retrieval = any(op in span_name for op in retrieval_ops)

                if is_retrieval:
                    attrs["openinference.span.kind"] = "RETRIEVER"
                else:
                    attrs["openinference.span.kind"] = "VECTOR_STORE"

        if "traceloop.entity.input" in attrs:
            try:
                entity_input = (
                    json.loads(attrs["traceloop.entity.input"])
                    if isinstance(attrs["traceloop.entity.input"], str)
                    else attrs["traceloop.entity.input"]
                )
                if isinstance(entity_input, dict):
                    if "method" in entity_input:
                        attrs["mcp.method.name"] = entity_input["method"]
                    if "params" in entity_input:
                        attrs["mcp.request.argument"] = json.dumps(entity_input["params"])
                    if "tool_name" in entity_input:
                        attrs["mcp.tool.name"] = entity_input["tool_name"]
                        if "arguments" in entity_input and isinstance(
                            entity_input["arguments"], dict
                        ):
                            attrs["mcp.tool.arguments"] = json.dumps(entity_input["arguments"])
            except (json.JSONDecodeError, TypeError, KeyError):
                pass

        has_mcp_signal = False
        if isinstance(attrs.get("mcp.method.name"), str) and attrs.get("mcp.method.name"):
            has_mcp_signal = True
        if isinstance(attrs.get("mcp.tool.name"), str) and attrs.get("mcp.tool.name"):
            has_mcp_signal = True
        if "mcp.request.argument" in attrs or "mcp.tool.arguments" in attrs:
            has_mcp_signal = True

        if (
            has_mcp_signal
            and "traceloop.entity.output" in attrs
            and "mcp.response.value" not in attrs
        ):
            attrs["mcp.response.value"] = attrs["traceloop.entity.output"]

        if attrs.get("mcp.method.name") == "initialize" and "traceloop.entity.output" in attrs:
            try:
                output = (
                    json.loads(attrs["traceloop.entity.output"])
                    if isinstance(attrs["traceloop.entity.output"], str)
                    else attrs["traceloop.entity.output"]
                )
                if "protocolVersion" in output:
                    attrs["mcp.protocol_version"] = output["protocolVersion"]
                if "serverInfo" in output and isinstance(output["serverInfo"], dict):
                    info = output["serverInfo"]
                    attrs["mcp.server.name"] = info.get("name", "")
                    attrs["mcp.server.version"] = info.get("version", "")
                if "capabilities" in output:
                    attrs["mcp.server.capabilities"] = json.dumps(output["capabilities"])[:2000]
            except (json.JSONDecodeError, TypeError, KeyError):
                pass

        if attrs.get("mcp.method.name") == "tools/list" and "traceloop.entity.output" in attrs:
            try:
                output = (
                    json.loads(attrs["traceloop.entity.output"])
                    if isinstance(attrs["traceloop.entity.output"], str)
                    else attrs["traceloop.entity.output"]
                )
                if "tools" in output and isinstance(output["tools"], list):
                    tools = output["tools"]
                    attrs["mcp.tools.count"] = len(tools)
                    tool_names = [t.get("name") for t in tools if "name" in t]
                    attrs["mcp.tools.names"] = json.dumps(tool_names)
            except (json.JSONDecodeError, TypeError, KeyError):
                pass

        span_kind = attrs.get("openinference.span.kind", "").upper()
        db_system = attrs.get("db.system", "").lower()

        if span_kind == "EMBEDDING":
            embeddings = []
            for key, value in attrs.items():
                if key.startswith("embedding.embeddings.") and key.endswith(".embedding.text"):
                    try:
                        parts = key.split(".")
                        if len(parts) >= 3:
                            index = int(parts[2])
                            embeddings.append({"index": index, "text": value})
                    except (ValueError, IndexError):
                        continue

            if embeddings:
                embeddings.sort(key=lambda x: x["index"])
                attrs["embeddings_data"] = json.dumps(embeddings)

                # Surface the embedded text as the span's human-readable input.
                # OpenInference does not set input.value for embeddings, and when
                # LangChain pre-tokenizes the raw input is opaque token IDs. Without a
                # meaningful input.value the span is later treated as empty/low-value
                # and dropped from the trace view, so populate it from the text.
                texts = [
                    e["text"]
                    for e in embeddings
                    if isinstance(e.get("text"), str) and e["text"].strip()
                ]
                if texts:
                    attrs["input.value"] = texts[0] if len(texts) == 1 else json.dumps(texts)

            # Only skip output if it's a REAL embedding operation from OpenLLMetry
            # (has actual embedding attributes, not just user's @span(kind="EMBEDDING"))
            has_embedding_attrs = any(
                k.startswith("embedding.") or k.startswith("gen_ai.embedding") for k in attrs.keys()
            )

            if has_embedding_attrs:
                attrs["neatlogs._skip_output_value"] = True

        if db_system == "chroma":
            doc_attrs = {}
            for key in [
                "db.chroma.add.ids_count",
                "db.chroma.add.embeddings_count",
                "db.chroma.add.metadatas_count",
                "db.chroma.add.documents_count",
                "db.chroma.upsert.ids_count",
                "db.chroma.upsert.embeddings_count",
                "db.chroma.upsert.metadatas_count",
                "db.chroma.upsert.documents_count",
            ]:
                if key in attrs:
                    doc_attrs[key.split(".")[-1]] = attrs[key]

            # Chroma's n_results is the requested top-k, not guaranteed returned count.
            if "db.chroma.query.n_results" in attrs:
                doc_attrs["requested_top_k"] = attrs["db.chroma.query.n_results"]

            if "db.chroma.query.include" in attrs:
                doc_attrs["include"] = attrs["db.chroma.query.include"]

            if doc_attrs:
                attrs["document_attributes"] = json.dumps(doc_attrs)

        elif db_system == "marqo":
            input_params = {}
            for key in ["marqo.limit", "marqo.hits_count", "marqo.filter"]:
                if key in attrs:
                    input_params[key.split(".")[-1]] = attrs[key]
            if input_params:
                attrs["retrieval_input_params"] = json.dumps(input_params)

            doc_attrs = {}
            for key in ["marqo.document_count", "marqo.items_processed"]:
                if key in attrs:
                    doc_attrs[key.split(".")[-1]] = attrs[key]
            if doc_attrs:
                attrs["document_attributes"] = json.dumps(doc_attrs)

        elif db_system == "qdrant":
            doc_attrs = {}
            if "qdrant.upsert.points_count" in attrs:
                doc_attrs["points_count"] = attrs["qdrant.upsert.points_count"]
            if doc_attrs:
                attrs["document_attributes"] = json.dumps(doc_attrs)

        elif db_system == "milvus":
            doc_attrs = {}
            for key in [
                "db.milvus.insert.data_count",
                "db.milvus.search.data_count",
                "db.milvus.search.limit",
                "db.milvus.search.output_fields_count",
                "db.milvus.search.result_count",
            ]:
                if key in attrs:
                    doc_attrs[key.replace("db.milvus.", "")] = attrs[key]
            if "db.milvus.search.filter" in attrs:
                doc_attrs["search.filter"] = attrs["db.milvus.search.filter"]
            if doc_attrs:
                attrs["document_attributes"] = json.dumps(doc_attrs)

        return attrs

    def _add_crewai_kickoff_telemetry(self, attrs: Dict[str, Any]) -> None:
        """
        Ensure CrewAI kickoff spans carry telemetry directly so downstream consumers
        do not need cross-batch Crew Created → kickoff correlation.
        """
        span_name = str(attrs.get("_span_name") or "")
        if not (span_name.startswith("Crew_") and span_name.endswith(".kickoff")):
            return

        # Fill in computed values only when OpenInference didn't already set them.
        if "crewai_version" not in attrs:
            try:
                import crewai  # type: ignore

                version = getattr(crewai, "__version__", None)
                if version:
                    attrs["crewai_version"] = str(version)
            except Exception:
                pass

        if "crew_number_of_tasks" not in attrs:
            count = self._coerce_collection_count(attrs.get("crew_tasks"))
            if count is not None:
                attrs["crew_number_of_tasks"] = count

        if "crew_number_of_agents" not in attrs:
            count = self._coerce_collection_count(attrs.get("crew_agents"))
            if count is not None:
                attrs["crew_number_of_agents"] = count

    def _coerce_collection_count(self, value: Any) -> Optional[int]:
        if value is None:
            return None

        if isinstance(value, bool):
            return int(value)
        if isinstance(value, int):
            return value
        if isinstance(value, float):
            try:
                return int(value)
            except Exception:
                return None
        if isinstance(value, (list, tuple, set, dict)):
            return len(value)

        if isinstance(value, str):
            s = value.strip()
            if not s:
                return None

            # Direct integer string.
            if re.fullmatch(r"\d+", s):
                try:
                    return int(s)
                except Exception:
                    return None

            # Try JSON first.
            try:
                parsed = json.loads(s)
                if isinstance(parsed, (list, tuple, set, dict)):
                    return len(parsed)
            except Exception:
                pass

            # Fallback for Python-repr style lists from some instrumentations.
            try:
                parsed = ast.literal_eval(s)
                if isinstance(parsed, (list, tuple, set, dict)):
                    return len(parsed)
            except Exception:
                pass

        return None

    def _add_crewai_token_usage_fallback(self, attrs: Dict[str, Any]) -> None:
        """
        Parse CrewAI aggregate token usage strings like:
          "total_tokens=67305 prompt_tokens=46983 cached_prompt_tokens=0 completion_tokens=20322 successful_requests=27"
        and map them to OpenInference-style token keys:
          - llm.token_count.prompt / completion / total
          - llm.token_count.prompt_details.cache_read (best-effort)
        Only applies when token_count fields are not already present.
        """
        # neatlogs.crew.token_usage: set by our OI CrewAI patch (_patch_openinference_crewai_crew_outputs)
        usage = attrs.get("neatlogs.crew.token_usage")
        if not isinstance(usage, str) or not usage:
            return

        if any(
            k in attrs
            for k in (
                "llm.token_count.prompt",
                "llm.token_count.completion",
                "llm.token_count.total",
            )
        ):
            return

        parsed: Dict[str, int] = {}
        for key, val in re.findall(r"([a-zA-Z_]+)=(\d+)", usage):
            try:
                parsed[key] = int(val)
            except Exception:
                continue

        if "prompt_tokens" in parsed:
            attrs["llm.token_count.prompt"] = parsed["prompt_tokens"]
        if "completion_tokens" in parsed:
            attrs["llm.token_count.completion"] = parsed["completion_tokens"]
        if "total_tokens" in parsed:
            attrs["llm.token_count.total"] = parsed["total_tokens"]

        # CrewAI reports cached_prompt_tokens; treat as cache-read input tokens.
        if "cached_prompt_tokens" in parsed:
            attrs["llm.token_count.prompt_details.cache_read"] = parsed["cached_prompt_tokens"]

    def _add_reasoning_tokens_from_output_value(self, attrs: Dict[str, Any]) -> None:
        """
        Fallback: parse output.value JSON to extract reasoning_tokens when
        llm.token_count.completion_details.reasoning is absent as a span attribute.

        Covers spans where the OpenInference OpenAI/LiteLLM instrumentor fails to
        extract it as a top-level attribute (e.g. Azure deployments via LiteLLM in
        CrewAI), even though the full API response in output.value contains the value.
        """
        if "llm.token_count.completion_details.reasoning" in attrs:
            return
        if "llm.usage.reasoning_tokens" in attrs:
            return

        output_value = attrs.get("output.value")
        if not isinstance(output_value, str):
            return

        try:
            parsed = json.loads(output_value)
            # Standard OpenAI / Azure chat completions response shape
            usage = parsed.get("usage") or {}
            details = usage.get("completion_tokens_details") or {}
            reasoning = details.get("reasoning_tokens")
            if reasoning and reasoning > 0:
                attrs["llm.token_count.completion_details.reasoning"] = reasoning
        except Exception:
            pass

    def _add_intermediate_steps(self, unified: Dict[str, Any]) -> None:
        """
        Populate `neatlogs.llm.intermediate_steps` when the LLM content includes ReAct-style
        markers (Thought/Context/Action/Action Input/Observation/Final Answer).

        This is intentionally compact and aggressively truncated to avoid payload bloat.
        Full tool outputs remain on tool spans.
        """

        if "neatlogs.llm.intermediate_steps" in unified:
            return
        if str(unified.get("neatlogs.span.kind", "")).lower() != "llm":
            return

        steps = self._extract_react_steps_from_messages(unified)
        if not steps:
            return

        unified["neatlogs.llm.intermediate_steps"] = json.dumps(steps, ensure_ascii=True)

    def _extract_react_steps_from_messages(self, unified: Dict[str, Any]) -> List[Dict[str, str]]:
        def _truncate(val: str, max_len: int) -> str:
            val = (val or "").strip()
            if len(val) <= max_len:
                return val
            return val[:max_len] + f"...(truncated,len={len(val)})"

        output_texts = self._collect_role_texts(
            unified, prefix="neatlogs.llm.output_messages", role="assistant"
        )
        steps = self._parse_react_steps(output_texts)
        if steps:
            return steps

        input_texts = self._collect_role_texts(
            unified, prefix="neatlogs.llm.input_messages", role="assistant"
        )
        return self._parse_react_steps(input_texts)

    def _collect_role_texts(self, unified: Dict[str, Any], prefix: str, role: str) -> List[str]:
        idx_re = re.compile(rf"^{re.escape(prefix)}\.(\d+)\.content$")
        idxs: set[int] = set()
        for k in unified.keys():
            m = idx_re.match(k)
            if m:
                try:
                    idxs.add(int(m.group(1)))
                except Exception:
                    pass

        texts: List[str] = []
        for i in sorted(idxs):
            r = unified.get(f"{prefix}.{i}.role")
            if not isinstance(r, str) or r.lower() != role:
                continue
            c = unified.get(f"{prefix}.{i}.content")
            if isinstance(c, str) and "thought:" in c.lower():
                texts.append(c[:20000])
        return texts

    def _parse_react_steps(self, texts: List[str]) -> List[Dict[str, str]]:
        if not texts:
            return []

        marker_re = re.compile(
            r"(?im)(?:^|\n)\s*(Thought|Context|Action|Action Input|Observation|Final Answer)\s*:\s*"
        )

        def _truncate(val: str, max_len: int) -> str:
            val = (val or "").strip()
            if len(val) <= max_len:
                return val
            return val[:max_len] + f"...(truncated,len={len(val)})"

        all_steps: List[Dict[str, str]] = []

        for text in texts:
            matches = list(marker_re.finditer(text))
            if not matches:
                continue

            cur: Dict[str, str] = {}

            def _commit() -> None:
                nonlocal cur
                if not cur:
                    return
                if not any(v for v in cur.values()):
                    cur = {}
                    return
                if all_steps and all_steps[-1] == cur:
                    cur = {}
                    return
                all_steps.append(cur)
                cur = {}

            for idx, m in enumerate(matches):
                label = m.group(1).strip().lower()
                start = m.end()
                end = matches[idx + 1].start() if idx + 1 < len(matches) else len(text)
                value = text[start:end].strip()

                if label == "thought" and cur:
                    _commit()

                if label == "thought":
                    cur["thought"] = _truncate(value, 600)
                elif label == "context":
                    cur["context"] = _truncate(value, 500)
                elif label == "action":
                    cur["action"] = _truncate(value, 200)
                elif label == "action input":
                    cur["action_input"] = _truncate(value, 1000)
                elif label == "observation":
                    cur["observation"] = _truncate(value, 500)
                elif label == "final answer":
                    cur["final_answer"] = _truncate(value, 1200)

            _commit()

        return all_steps

    def _looks_like_http(self, attrs: Dict[str, Any]) -> bool:
        for k in (
            "http.method",
            "http.request.method",
            "http.url",
            "url.full",
            "http.status_code",
            "http.response.status_code",
            "http.route",
        ):
            if k in attrs:
                return True
        return any(key.startswith("http.") for key in attrs.keys())

    def _add_http_canonical_io(self, attrs: Dict[str, Any]) -> None:
        self.sanitize_http_attributes(attrs)
        method = attrs.get("http.request.method") or attrs.get("http.method")
        sanitized_url = self._sanitized_http_url(attrs)
        if method and sanitized_url:
            attrs["input.value"] = json.dumps(
                {"method": str(method).upper(), "url": sanitized_url},
                separators=(",", ":"),
            )
            attrs["input.mime_type"] = "application/json"
        else:
            attrs.pop("input.value", None)
            attrs.pop("input.mime_type", None)

        status = attrs.get("http.response.status_code")
        if status is None:
            status = attrs.get("http.status_code")
        if status is not None:
            attrs["output.value"] = json.dumps({"status": status}, separators=(",", ":"))
            attrs["output.mime_type"] = "application/json"
        else:
            attrs.pop("output.value", None)
            attrs.pop("output.mime_type", None)

    def _sanitized_http_url(self, attrs: Dict[str, Any]) -> Optional[str]:
        raw_url = attrs.get("url.full") or attrs.get("http.url")
        if raw_url:
            return self._sanitize_url(str(raw_url))

        scheme = attrs.get("url.scheme") or attrs.get("http.scheme") or "http"
        host = attrs.get("server.address") or attrs.get("net.peer.name") or attrs.get("http.host")
        if not host:
            return None
        host = str(host).split("@")[-1]
        if host.startswith("[") and "]" in host:
            host = host[1 : host.index("]")]
        elif host.count(":") == 1:
            candidate, candidate_port = host.rsplit(":", 1)
            if candidate_port.isdigit():
                host = candidate
        port = attrs.get("server.port") or attrs.get("net.peer.port")
        netloc = f"[{host}]" if ":" in host else host
        if port:
            netloc = f"{netloc}:{port}"
        path = attrs.get("url.path") or attrs.get("http.target") or attrs.get("http.route") or ""
        path = self._sanitize_path(str(path))
        return self._sanitize_url(urlunsplit((str(scheme), netloc, path or "/", "", "")))

    def _sanitize_url(self, raw_url: str) -> str:
        try:
            parts = urlsplit(raw_url)
        except ValueError:
            return "/"
        host = parts.hostname or ""
        netloc = host
        if ":" in host and not host.startswith("["):
            netloc = f"[{host}]"
        try:
            port = parts.port
        except ValueError:
            port = None
        if port is not None:
            netloc = f"{netloc}:{port}"
        return urlunsplit((parts.scheme, netloc, parts.path or "/", "", ""))

    def _sanitize_path(self, raw_path: str) -> str:
        try:
            parsed = urlsplit(raw_path)
        except ValueError:
            return "/"
        if parsed.scheme or parsed.netloc:
            return parsed.path or "/"
        return raw_path.split("?", 1)[0].split("#", 1)[0] or "/"

    def sanitize_http_attributes(self, attrs: Dict[str, Any]) -> None:
        for key in ("http.url", "url.full"):
            if attrs.get(key):
                attrs[key] = self._sanitize_url(str(attrs[key]))
        for key in ("http.target", "url.path", "http.route"):
            if attrs.get(key):
                attrs[key] = self._sanitize_path(str(attrs[key]))

        for key in list(attrs):
            lowered = key.lower()
            is_header = "header" in lowered
            is_body_payload = "body" in lowered and not lowered.endswith(".body.size")
            is_url_component = lowered in {"url.query", "url.fragment"}
            if is_header or is_body_payload or is_url_component:
                attrs.pop(key, None)

    def _extract_operational_metrics(
        self, span: ReadableSpan, attrs: Dict[str, Any]
    ) -> Dict[str, Any]:
        computed = {}

        duration_ns = span.end_time - span.start_time
        computed["neatlogs.metrics.duration_ms"] = duration_ns / 1_000_000

        # Skip event-based TTFT computation if already set live by a streaming patch
        # (OpenAI/Anthropic/LangChain/LiteLLM patches set these directly on the span)
        if attrs.get("neatlogs.llm.metrics.ttft_ms") is not None:
            return computed

        # Google GenAI emits "gen_ai.content.chunk" on every text chunk — use for TTFT + streaming_time_to_generate
        chunk_timestamps = []
        if span.events:
            for event in span.events:
                if event.name == "gen_ai.content.chunk":
                    chunk_timestamps.append(event.timestamp)

        if chunk_timestamps:
            first_ns = chunk_timestamps[0]
            ttft_ms = round((first_ns - span.start_time) / 1_000_000, 3)
            computed["neatlogs.llm.metrics.ttft_ms"] = ttft_ms

            if len(chunk_timestamps) >= 2:
                last_ns = chunk_timestamps[-1]
                stg_ms = round((last_ns - first_ns) / 1_000_000, 3)
                computed["neatlogs.llm.metrics.streaming_time_to_generate_ms"] = stg_ms

        return computed

    def _upcycle_events(self, span: ReadableSpan) -> Dict[str, Any]:
        upcycled: Dict[str, Any] = {}
        retriever_docs: List[Dict[str, Any]] = []

        for event in span.events:
            if event.name == "db.query.result":
                e_attrs = event.attributes
                doc: Dict[str, Any] = {
                    "timestamp": (
                        event.timestamp.isoformat()
                        if hasattr(event.timestamp, "isoformat")
                        else str(event.timestamp)
                    )
                }
                if "db.query.result.id" in e_attrs:
                    doc["id"] = e_attrs["db.query.result.id"]
                if "db.query.result.distance" in e_attrs:
                    doc["distance"] = e_attrs["db.query.result.distance"]
                if "db.query.result.document" in e_attrs:
                    doc["document"] = e_attrs["db.query.result.document"]
                if "db.query.result.metadata" in e_attrs:
                    metadata = e_attrs["db.query.result.metadata"]
                    try:
                        doc["metadata"] = (
                            json.loads(metadata) if isinstance(metadata, str) else metadata
                        )
                    except Exception:
                        doc["metadata"] = str(metadata)

                for field in ["_id", "title", "text", "category", "_score"]:
                    if field in e_attrs:
                        doc[field] = e_attrs[field]

                retriever_docs.append(doc)

            elif event.name == "db.search.result":
                e_attrs = event.attributes
                doc = {
                    "timestamp": (
                        event.timestamp.isoformat()
                        if hasattr(event.timestamp, "isoformat")
                        else str(event.timestamp)
                    )
                }
                if "db.search.query.id" in e_attrs:
                    doc["query_id"] = e_attrs["db.search.query.id"]
                if "db.search.result.id" in e_attrs:
                    doc["result_id"] = e_attrs["db.search.result.id"]
                if "db.search.result.distance" in e_attrs:
                    doc["distance"] = e_attrs["db.search.result.distance"]
                if "db.search.result.entity" in e_attrs:
                    doc["entity"] = e_attrs["db.search.result.entity"]
                retriever_docs.append(doc)

            elif event.name == "db.query.embeddings":
                e_attrs = event.attributes
                vector = e_attrs.get("db.query.embeddings.vector") or e_attrs.get("vector")
                if vector and isinstance(vector, (list, tuple, bytes)):
                    upcycled["neatlogs.db.query.embeddings.dimension"] = len(vector)
                    if self.debug:
                        self.logger.debug(f"Calculated embedding dimension: {len(vector)}")

        if retriever_docs:
            upcycled["retrieval_documents"] = json.dumps(retriever_docs)

        return upcycled

    def _apply_namespace_mapping(self, attrs: Dict[str, Any]) -> Dict[str, Any]:
        unified: Dict[str, Any] = {k: v for k, v in attrs.items() if k.startswith("neatlogs.")}
        mappings = self.mapping.get("mappings", {})

        consumed: set[str] = set()
        self._map_recursive(mappings, attrs, unified, consumed)

        span_kind_config = mappings.get("span_kind", {})
        explicit_kind = normalize_explicit_span_kind(
            attrs,
            span_kind_config.get("values", {}) if isinstance(span_kind_config, dict) else {},
        )
        if explicit_kind:
            unified["neatlogs.span.kind"] = explicit_kind

        keep_as_is = self.mapping.get("keep_as_is", {}).get("attributes", [])
        for key in keep_as_is:
            if key in attrs:
                unified[key] = attrs[key]

        ignore_patterns = self.mapping.get("ignore", {}).get("patterns", [])
        for key, value in attrs.items():
            if key.startswith("neatlogs.") or key in unified or key in keep_as_is:
                continue
            if key in consumed:
                continue

            should_ignore = False
            for pattern in ignore_patterns:
                if pattern.endswith("*") and key.startswith(pattern[:-1]):
                    should_ignore = True
                    break
                if key == pattern:
                    should_ignore = True
                    break

            # Unmapped attributes are not copied — they stay on the OTel span
            # natively and are exported via OTLP as-is.

        # Ensure neatlogs.span.kind is always set (for simplified view)
        if "neatlogs.span.kind" not in unified:
            oi_kind = attrs.get("openinference.span.kind")
            if oi_kind:
                unified["neatlogs.span.kind"] = str(oi_kind).lower()
            else:
                # Fallback: infer from span name
                from ..span_kinds.mapping import infer_span_kind_from_name

                span_name = attrs.get("_span_name", "")  # Will be set by span processor
                if span_name:
                    inferred_kind = infer_span_kind_from_name(span_name)
                    unified["neatlogs.span.kind"] = inferred_kind.lower()

        # Detect RERANKER operations. STRONG signals from the actual model call
        # (llm.request.type / gen_ai.operation.name == "rerank") override, since they
        # describe what the call DID. The WEAK signal — "rerank" merely appearing in the
        # span NAME — must NOT override a kind the user explicitly set: a route handler
        # named `rerank_documents` decorated @span(kind="WORKFLOW") is the feature's
        # trace root, and forcing it to RERANKER makes the whole trace unrootable
        # (the backend only roots WORKFLOW/CHAIN/AGENT/MCP_TOOL). Apply the name-only
        # heuristic exactly like the inference block above: only when no explicit kind exists.
        llm_request_type = attrs.get("llm.request.type", "").lower()
        gen_ai_operation = attrs.get("gen_ai.operation.name", "").lower()
        span_name_lower = attrs.get("_span_name", "").lower()
        explicit_kind = resolve_explicit_span_kind(attrs)

        if llm_request_type == "rerank" or gen_ai_operation == "rerank":
            unified["neatlogs.span.kind"] = "reranker"
        elif "rerank" in span_name_lower and not explicit_kind:
            unified["neatlogs.span.kind"] = "reranker"

        span_kind = (
            attrs.get("neatlogs.span.kind") or attrs.get("openinference.span.kind") or ""
        ).lower()
        if span_kind not in ("embedding", "retriever", "vector_store"):
            unified.pop("neatlogs.vectordb.embedding_model", None)

        # Instrumentors emit the embedded text on neatlogs.embedding.text, but the
        # backend maps embedding input from neatlogs.embedding.input. Alias so the
        # human-readable text lands in input_value (else the span looks empty and is
        # dropped from the simplified view).
        if span_kind == "embedding" and unified.get("neatlogs.embedding.text") is not None:
            unified.setdefault("neatlogs.embedding.input", unified["neatlogs.embedding.text"])

        if self.debug:
            self.logger.debug(
                "[ScopeDetectionFinal] span_name=%s scope=%s framework=%s",
                attrs.get("_span_name"),
                attrs.get("neatlogs.instrumentation.name"),
                unified.get("neatlogs.framework"),
            )

        self._fill_provider_gaps(attrs, unified)

        return unified

    def _fill_provider_gaps(self, attrs: Dict[str, Any], unified: Dict[str, Any]) -> None:
        """
        Fill neatlogs.llm.provider and neatlogs.llm.system when OpenInference doesn't set them.

        OpenInference sets llm.provider for openai/anthropic/google_genai/bedrock/cohere but
        NOT for groq, mistralai, vertexai. The scope-based detection in
        enrich_with_scope_detection() already writes neatlogs.provider from the instrumentation
        scope name, so we use that as a fallback. Model-name inference is the last resort.
        """
        # --- neatlogs.llm.provider ---
        if not unified.get("neatlogs.llm.provider"):
            # Fallback 1: scope-detected provider (set by enrich_with_scope_detection)
            scope_provider = unified.get("neatlogs.provider") or attrs.get("neatlogs.provider", "")
            if scope_provider:
                unified["neatlogs.llm.provider"] = scope_provider
            else:
                # Fallback 2: infer from model name prefix
                model = (
                    attrs.get("llm.model_name")
                    or attrs.get("gen_ai.request.model")
                    or attrs.get("llm.model")
                    or ""
                )
                inferred = self._infer_provider_from_model(str(model))
                if inferred:
                    unified["neatlogs.llm.provider"] = inferred

        # --- neatlogs.llm.system ---
        if not unified.get("neatlogs.llm.system"):
            provider = (
                unified.get("neatlogs.llm.provider") or unified.get("neatlogs.provider") or ""
            ).lower()
            system = _PROVIDER_TO_SYSTEM.get(provider, "")
            if system:
                unified["neatlogs.llm.system"] = system

    def _infer_provider_from_model(self, model: str) -> str:
        """Infer LLM provider from model name prefix as a last resort."""
        if not model:
            return ""
        m = model.lower()
        # OpenAI model families
        if m.startswith(("gpt-", "o1-", "o3-", "o4-", "text-embedding-", "text-davinci-")):
            return "openai"
        # Anthropic
        if m.startswith("claude-"):
            return "anthropic"
        # Google
        if m.startswith(("gemini-", "gemma-")):
            return "google"
        # Mistral
        if m.startswith(("mistral-", "mixtral-")):
            return "mistralai"
        # Cohere
        if m.startswith(("command-", "embed-english", "embed-multilingual")):
            return "cohere"
        # Bedrock model IDs (e.g. "anthropic.claude-3-5-sonnet-v1:0", "meta.llama3-8b-instruct-v1:0")
        if m.startswith(("anthropic.", "meta.", "amazon.", "nova-", "titan-")):
            return "aws"
        # xAI
        if m.startswith("grok-"):
            return "xai"
        # DeepSeek
        if m.startswith("deepseek-"):
            return "deepseek"
        return ""

    def _map_recursive(
        self,
        mapping_tier: Dict[str, Any],
        source: Dict[str, Any],
        target: Dict[str, Any],
        consumed: set[str],
    ):
        for _, config in mapping_tier.items():
            if not isinstance(config, dict):
                continue

            if (
                isinstance(config, dict)
                and "mappings" in config
                and isinstance(config["mappings"], dict)
            ):
                self._map_recursive(config["mappings"], source, target, consumed)

            if isinstance(config, dict):
                for child_key, child_cfg in config.items():
                    if child_key in (
                        "mappings",
                        "description",
                        "priority",
                        "values",
                        "sources",
                        "target",
                        "indexed",
                        "template",
                        "target_content",
                        "target_template",
                    ):
                        continue
                    if not isinstance(child_cfg, dict):
                        continue
                    if any(k in child_cfg for k in ("target", "sources", "mappings", "indexed")):
                        self._map_recursive({child_key: child_cfg}, source, target, consumed)
                        continue

                    # Some tiers are purely organizational (e.g. metrics.llm.time_per_output_token)
                    # and don't contain leaf mapping keys until 2+ levels down. Always descend into
                    # nested dicts here to reach those leaf mappings.
                    nested_tier = {k: v for k, v in child_cfg.items() if isinstance(v, dict)}
                    if nested_tier:
                        self._map_recursive(nested_tier, source, target, consumed)

            target_key = config.get("target")
            if not target_key:
                continue

"""Final export filtering for unsupported HTTP transport spans."""

from __future__ import annotations

from collections.abc import Callable, Sequence

from opentelemetry.sdk.trace import ReadableSpan
from opentelemetry.sdk.trace.export import SpanExporter, SpanExportResult

from .media_exporter import release_span_media
from .span_processor import is_http_span


class HttpFilteringSpanExporter(SpanExporter):
    """Drop HTTP spans while releasing their private media allocations."""

    def __init__(
        self,
        inner: SpanExporter,
        *,
        media_store=None,
        on_accepted: Callable[[ReadableSpan], None] | None = None,
        on_rejected: Callable[[ReadableSpan], None] | None = None,
    ) -> None:
        self._inner = inner
        self._media_store = media_store
        self._on_accepted = on_accepted
        self._on_rejected = on_rejected

    def export(self, spans: Sequence[ReadableSpan]) -> SpanExportResult:
        kept: list[ReadableSpan] = []
        for span in spans:
            if is_http_span(span):
                release_span_media(self._media_store, span)
                if self._on_rejected is not None:
                    self._on_rejected(span)
                continue
            kept.append(span)
        if not kept:
            return SpanExportResult.SUCCESS
        result = self._inner.export(kept)
        callback = self._on_accepted if result == SpanExportResult.SUCCESS else self._on_rejected
        if callback is not None:
            for span in kept:
                callback(span)
        return result

    def shutdown(self) -> None:
        self._inner.shutdown()

    def force_flush(self, timeout_millis: int = 30000) -> bool:
        result = self._inner.force_flush(timeout_millis)
        return True if result is None else bool(result)

"""Fail-closed masking at Neatlogs' final telemetry export boundary."""

from __future__ import annotations

import asyncio
import copy
import inspect
import logging
import queue
import threading
import time
from collections.abc import Mapping, Sequence
from dataclasses import dataclass
from typing import Any, Callable

try:
    from opentelemetry.sdk._logs import ReadableLogRecord
    from opentelemetry.sdk._logs.export import LogRecordExporter, LogRecordExportResult
except ImportError:  # OpenTelemetry 1.35-1.38 compatibility
    from opentelemetry.sdk._logs import LogData as ReadableLogRecord
    from opentelemetry.sdk._logs.export import (
        LogExporter as LogRecordExporter,
        LogExportResult as LogRecordExportResult,
    )

from opentelemetry.sdk.resources import Resource
from opentelemetry.sdk.trace import Event, ReadableSpan
from opentelemetry.sdk.trace.export import SpanExporter, SpanExportResult
from opentelemetry.trace import Link, Status, StatusCode

from .delivery import DeliveryDiagnostics
from .mask import effective_mask

logger = logging.getLogger(__name__)
_MASK_POOL_SIZE = 4


@dataclass(frozen=True)
class MaskContext:
    """Deadline/cancellation information supplied to context-aware masks."""

    signal_type: str
    timeout_seconds: float
    deadline_monotonic: float
    cancelled: threading.Event


def _accepts_context(mask: Callable) -> bool:
    """Require an explicit keyword-only context opt-in.

    The original public callback contract accepted one positional snapshot.
    Binding a second positional argument breaks callbacks that happen to have
    an unrelated optional positional parameter.
    """
    try:
        parameter = inspect.signature(mask).parameters.get("context")
    except (TypeError, ValueError):
        return False
    return parameter is not None and parameter.kind is inspect.Parameter.KEYWORD_ONLY


def _mask_call(
    mask: Callable,
    snapshot: dict[str, Any],
    timeout_seconds: float,
    context: MaskContext,
):
    result = mask(snapshot, context=context) if _accepts_context(mask) else mask(snapshot)
    if inspect.isawaitable(result):
        return asyncio.run(asyncio.wait_for(result, timeout=timeout_seconds))
    return result


class _MaskWorkerPool:
    """Fixed workers created before atexit; submissions never create threads."""

    def __init__(self, max_workers: int = _MASK_POOL_SIZE) -> None:
        self._tasks: queue.Queue[Callable[[], None]] = queue.Queue()
        self._slots = threading.BoundedSemaphore(max_workers)
        self._workers = [
            threading.Thread(
                target=self._run,
                name=f"neatlogs-mask-{index}",
                daemon=True,
            )
            for index in range(max_workers)
        ]
        for worker in self._workers:
            worker.start()

    def _run(self) -> None:
        while True:
            operation = self._tasks.get()
            try:
                operation()
            finally:
                self._slots.release()

    def submit(self, operation: Callable[[], None]) -> bool:
        if not self._slots.acquire(blocking=False):
            return False
        self._tasks.put_nowait(operation)
        return True


_mask_pool: _MaskWorkerPool | None = None
_mask_pool_lock = threading.Lock()


def _get_mask_pool() -> _MaskWorkerPool:
    global _mask_pool
    with _mask_pool_lock:
        if _mask_pool is None:
            _mask_pool = _MaskWorkerPool()
        return _mask_pool


class _MaskRunner:
    def __init__(self, timeout_seconds: float = 5.0, max_workers: int = 4) -> None:
        self._timeout_seconds = timeout_seconds
        self._max_workers = max_workers
        self._pool = _get_mask_pool()
        self._closed = threading.Event()
        self._active_lock = threading.Lock()
        self._active_cancellations: set[threading.Event] = set()

    def apply(self, mask: Callable, snapshot: dict[str, Any]) -> dict[str, Any] | None:
        return self.apply_many(((mask, snapshot),))[0]

    def apply_many(
        self,
        items: Sequence[tuple[Callable, dict[str, Any]]],
    ) -> list[dict[str, Any] | None]:
        """Mask a batch concurrently under one bounded export-worker deadline."""
        if not items:
            return []
        results: list[dict[str, Any] | None] = [None] * len(items)
        deadline = time.monotonic() + self._timeout_seconds
        result_queue: queue.Queue[tuple[int, bool, Any, dict[str, Any]]] = queue.Queue()
        pending = list(range(len(items)))
        active: dict[int, threading.Event] = {}

        def launch(index: int) -> bool:
            if self._closed.is_set():
                return False
            mask, snapshot = items[index]
            candidate = copy.deepcopy(snapshot)
            cancelled = threading.Event()
            context = MaskContext(
                signal_type=str(snapshot.get("signal") or "span"),
                timeout_seconds=max(0.0, deadline - time.monotonic()),
                deadline_monotonic=deadline,
                cancelled=cancelled,
            )
            active[index] = cancelled
            with self._active_lock:
                self._active_cancellations.add(cancelled)

            def run() -> None:
                try:
                    remaining = max(0.001, deadline - time.monotonic())
                    result = _mask_call(mask, candidate, remaining, context)
                    result_queue.put((index, True, result, candidate))
                except BaseException as exc:
                    result_queue.put((index, False, exc, candidate))
                finally:
                    with self._active_lock:
                        self._active_cancellations.discard(cancelled)

            if not self._pool.submit(run):
                with self._active_lock:
                    self._active_cancellations.discard(cancelled)
                active.pop(index, None)
                return False
            return True

        while pending and len(active) < self._max_workers:
            if not launch(pending[0]):
                break
            pending.pop(0)

        while active and time.monotonic() < deadline:
            try:
                index, succeeded, result, candidate = result_queue.get(
                    timeout=max(0.001, deadline - time.monotonic())
                )
            except queue.Empty:
                break
            active.pop(index, None)
            if succeeded and result is None:
                # A mask returning None drops the item entirely, matching the
                # documented contract in the TypeScript and Go SDKs.
                results[index] = None
            elif succeeded and isinstance(result, Mapping):
                results[index] = dict(result)
            elif succeeded:
                logger.error("[neatlogs] mask returned a non-mapping; telemetry item dropped")
            else:
                logger.error(
                    "[neatlogs] mask failed; telemetry item dropped (%s)",
                    type(result).__name__,
                )
            while pending and len(active) < self._max_workers:
                if not launch(pending[0]):
                    break
                pending.pop(0)

        if active or pending:
            for cancelled in active.values():
                cancelled.set()
            logger.error(
                "[neatlogs] mask deadline/capacity exhausted; %d telemetry item(s) dropped",
                len(active) + len(pending),
            )
        return results

    def shutdown(self) -> None:
        self._closed.set()
        with self._active_lock:
            for cancelled in self._active_cancellations:
                cancelled.set()


def _attrs(value: Any) -> dict[str, Any]:
    if not isinstance(value, Mapping):
        return {}
    return {str(key): item for key, item in value.items() if item is not None}


def _span_snapshot(span: ReadableSpan) -> dict[str, Any]:
    return {
        "signal": "span",
        "name": span.name,
        "attributes": dict(span.attributes or {}),
        "events": [
            {
                "name": event.name,
                "timestamp": event.timestamp,
                "attributes": dict(event.attributes or {}),
            }
            for event in span.events
        ],
        "links": [
            {
                "trace_id": f"{link.context.trace_id:032x}",
                "span_id": f"{link.context.span_id:016x}",
                "attributes": dict(link.attributes or {}),
            }
            for link in span.links
        ],
        "resource": {"attributes": dict(span.resource.attributes or {})},
        "status": {
            "code": span.status.status_code.name,
            "description": span.status.description,
        },
    }


def _masked_span(span: ReadableSpan, snapshot: Mapping[str, Any]) -> ReadableSpan:
    events = []
    for item in snapshot.get("events", ()):
        if not isinstance(item, Mapping):
            continue
        events.append(
            Event(
                str(item.get("name") or "event"),
                attributes=_attrs(item.get("attributes")),
                timestamp=item.get("timestamp"),
            )
        )

    links = []
    for index, item in enumerate(snapshot.get("links", ())):
        if index >= len(span.links) or not isinstance(item, Mapping):
            continue
        links.append(Link(span.links[index].context, attributes=_attrs(item.get("attributes"))))

    resource_data = snapshot.get("resource")
    resource_attrs = (
        _attrs(resource_data.get("attributes")) if isinstance(resource_data, Mapping) else {}
    )
    status_data = snapshot.get("status")
    status = span.status
    if isinstance(status_data, Mapping):
        code_name = str(status_data.get("code") or span.status.status_code.name)
        try:
            code = StatusCode[code_name]
        except KeyError:
            code = span.status.status_code
        status = Status(code, status_data.get("description"))

    attributes = _attrs(snapshot.get("attributes"))
    attributes.pop("neatlogs.mask_id", None)
    return ReadableSpan(
        name=str(snapshot.get("name") or span.name),
        context=span.context,
        parent=span.parent,
        resource=Resource(resource_attrs, schema_url=span.resource.schema_url),
        attributes=attributes,
        events=events,
        links=links,
        kind=span.kind,
        status=status,
        start_time=span.start_time,
        end_time=span.end_time,
        instrumentation_scope=span.instrumentation_scope,
    )


class MaskingSpanExporter(SpanExporter):
    """Clone, mask and export spans; callback failures drop only the affected span."""

    def __init__(
        self,
        inner: SpanExporter,
        mask: Callable | None,
        timeout_seconds: float = 5.0,
        diagnostics: DeliveryDiagnostics | None = None,
        media_store: Any | None = None,
        doctor_capture: bool = False,
        on_dropped: Callable[[ReadableSpan], None] | None = None,
    ) -> None:
        self._inner = inner
        self._global_mask = mask
        self._runner = _MaskRunner(timeout_seconds)
        self._diagnostics = diagnostics
        self._media_store = media_store
        self._doctor_capture = doctor_capture
        self._on_dropped = on_dropped

    def export(self, spans: Sequence[ReadableSpan]) -> SpanExportResult:
        prepared: list[ReadableSpan | None] = [None] * len(spans)
        masked_inputs: list[tuple[Callable, dict[str, Any]]] = []
        masked_indexes: list[int] = []
        for index, span in enumerate(spans):
            snapshot = _span_snapshot(span)
            mask = effective_mask(snapshot, self._global_mask)
            if mask is None:
                prepared[index] = span
                continue
            masked_inputs.append((mask, snapshot))
            masked_indexes.append(index)
        masked_results = self._runner.apply_many(masked_inputs)
        from .media import current_media_store
        from .media_exporter import release_removed_media

        for index, (_, original), masked in zip(masked_indexes, masked_inputs, masked_results):
            release_removed_media(
                self._media_store or current_media_store(),
                original,
                masked,
            )
            if masked is not None:
                prepared[index] = _masked_span(spans[index], masked)
            else:
                if self._on_dropped is not None:
                    self._on_dropped(spans[index])
                if self._diagnostics is not None:
                    self._diagnostics.record_masked_drop("span")
        kept = [span for span in prepared if span is not None]
        if not kept:
            return SpanExportResult.SUCCESS
        if self._doctor_capture:
            try:
                from ..doctor_v2 import capture_prepared_spans

                capture_prepared_spans(kept)
            except Exception:
                logger.error("[neatlogs] doctor capture failed safely")
        return self._inner.export(kept)

    def force_flush(self, timeout_millis: int = 30000) -> bool:
        result = self._inner.force_flush(timeout_millis)
        return True if result is None else bool(result)

    def shutdown(self) -> None:
        self._runner.shutdown()
        try:
            self._inner.shutdown()
        finally:
            if self._doctor_capture:
                from ..doctor_v2 import clear_doctor_capture

                clear_doctor_capture()


def _log_snapshot(item: ReadableLogRecord) -> dict[str, Any]:
    record = item.log_record
    resource = getattr(item, "resource", None) or getattr(record, "resource", None)
    return {
        "signal": "log",
        "name": item.instrumentation_scope.name if item.instrumentation_scope else "log",
        "body": record.body,
        "attributes": dict(record.attributes or {}),
        "resource": {"attributes": dict(resource.attributes or {}) if resource else {}},
        "severity_text": record.severity_text,
        "event_name": record.event_name,
    }


class MaskingLogExporter(LogRecordExporter):
    """Apply the same global fail-closed mask contract to correlated logs."""

    def __init__(
        self,
        inner: LogRecordExporter,
        mask: Callable | None,
        timeout_seconds: float = 5.0,
        diagnostics: DeliveryDiagnostics | None = None,
        media_store: Any | None = None,
    ) -> None:
        self._inner = inner
        self._mask = mask
        self._runner = _MaskRunner(timeout_seconds)
        self._diagnostics = diagnostics
        self._media_store = media_store

    def export(self, batch: Sequence[ReadableLogRecord]) -> LogRecordExportResult:
        if self._mask is None:
            return self._inner.export(batch)
        kept = []
        snapshots = [(self._mask, _log_snapshot(item)) for item in batch]
        masked_results = self._runner.apply_many(snapshots)
        from .media import current_media_store
        from .media_exporter import release_removed_media

        for item, (_, original), masked in zip(batch, snapshots, masked_results):
            release_removed_media(self._media_store or current_media_store(), original, masked)
            if masked is None:
                if self._diagnostics is not None:
                    self._diagnostics.record_masked_drop("log")
                continue
            clone = copy.copy(item)
            clone_record = copy.copy(item.log_record)
            clone_record.body = masked.get("body")
            clone_record.attributes = _attrs(masked.get("attributes"))
            clone_record.severity_text = masked.get("severity_text")
            clone_record.event_name = masked.get("event_name")
            object.__setattr__(clone, "log_record", clone_record)
            resource_data = masked.get("resource")
            resource_attrs = (
                _attrs(resource_data.get("attributes"))
                if isinstance(resource_data, Mapping)
                else {}
            )
            original_resource = getattr(item, "resource", None) or getattr(
                item.log_record, "resource", None
            )
            masked_resource = Resource(
                resource_attrs,
                schema_url=original_resource.schema_url if original_resource else None,
            )
            if hasattr(clone, "resource"):
                object.__setattr__(clone, "resource", masked_resource)
            elif hasattr(clone_record, "resource"):
                object.__setattr__(clone_record, "resource", masked_resource)
            kept.append(clone)
        if not kept:
            return LogRecordExportResult.SUCCESS
        return self._inner.export(kept)

    def force_flush(self, timeout_millis: int = 10000) -> bool:
        # LogRecordExporter.force_flush became abstract in OpenTelemetry 1.44.
        # NeatLogs still supports earlier SDK releases whose exporters do not
        # expose it, so absence means there is no exporter-level buffer to flush.
        force_flush = getattr(self._inner, "force_flush", None)
        if force_flush is None:
            return True
        result = force_flush(timeout_millis)
        return True if result is None else bool(result)

    def shutdown(self) -> None:
        self._runner.shutdown()
        self._inner.shutdown()

