{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://schemas.neatlogs.com/telemetry/v2/neatlogs-telemetry.schema.json",
  "title": "NeatLogs Canonical Telemetry Span Envelope v2",
  "description": "The language-neutral canonical span representation used after capture normalization and before masking/export.",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "schema_version",
    "trace_id",
    "span_id",
    "parent_span_id",
    "name",
    "kind",
    "ownership",
    "wrapper",
    "input",
    "output",
    "status",
    "error",
    "code",
    "provenance",
    "conflicts",
    "semantic",
    "attributes"
  ],
  "properties": {
    "schema_version": {
      "const": 2
    },
    "trace_id": {
      "$ref": "#/$defs/traceId"
    },
    "span_id": {
      "$ref": "#/$defs/spanId"
    },
    "parent_span_id": {
      "oneOf": [
        {
          "$ref": "#/$defs/spanId"
        },
        {
          "type": "null"
        }
      ]
    },
    "name": {
      "type": "string",
      "minLength": 1,
      "maxLength": 1024
    },
    "kind": {
      "$ref": "#/$defs/spanKind"
    },
    "start_time_unix_nano": {
      "$ref": "#/$defs/uint64String"
    },
    "end_time_unix_nano": {
      "$ref": "#/$defs/uint64String"
    },
    "ownership": {
      "$ref": "#/$defs/ownership"
    },
    "wrapper": {
      "$ref": "#/$defs/wrapper"
    },
    "input": {
      "$ref": "#/$defs/typedValue"
    },
    "output": {
      "$ref": "#/$defs/typedValue"
    },
    "status": {
      "$ref": "#/$defs/status"
    },
    "error": {
      "oneOf": [
        {
          "$ref": "#/$defs/error"
        },
        {
          "type": "null"
        }
      ]
    },
    "code": {
      "oneOf": [
        {
          "$ref": "#/$defs/codeLocation"
        },
        {
          "type": "null"
        }
      ]
    },
    "provenance": {
      "type": "array",
      "items": {
        "$ref": "#/$defs/provenance"
      }
    },
    "conflicts": {
      "type": "array",
      "items": {
        "$ref": "#/$defs/conflict"
      }
    },
    "semantic": {
      "$ref": "#/$defs/semantic"
    },
    "attributes": {
      "type": "object",
      "description": "Non-canonical source attributes retained for compatibility and debugging. They never override canonical fields.",
      "additionalProperties": {
        "$ref": "#/$defs/jsonValue"
      }
    }
  },
  "allOf": [
    {
      "if": {
        "properties": {
          "kind": {
            "const": "LLM"
          }
        }
      },
      "then": {
        "properties": {
          "semantic": {
            "$ref": "#/$defs/llmSemantic"
          }
        }
      }
    },
    {
      "if": {
        "properties": {
          "kind": {
            "enum": [
              "TOOL",
              "MCP_TOOL"
            ]
          }
        }
      },
      "then": {
        "properties": {
          "semantic": {
            "$ref": "#/$defs/toolSemantic"
          }
        }
      }
    },
    {
      "if": {
        "properties": {
          "kind": {
            "const": "RETRIEVER"
          }
        }
      },
      "then": {
        "properties": {
          "semantic": {
            "$ref": "#/$defs/retrieverSemantic"
          }
        }
      }
    },
    {
      "if": {
        "properties": {
          "kind": {
            "const": "RERANKER"
          }
        }
      },
      "then": {
        "properties": {
          "semantic": {
            "$ref": "#/$defs/rerankerSemantic"
          }
        }
      }
    },
    {
      "if": {
        "properties": {
          "kind": {
            "const": "EMBEDDING"
          }
        }
      },
      "then": {
        "properties": {
          "semantic": {
            "$ref": "#/$defs/embeddingSemantic"
          }
        }
      }
    },
    {
      "if": {
        "properties": {
          "kind": {
            "const": "VECTOR_STORE"
          }
        }
      },
      "then": {
        "properties": {
          "semantic": {
            "$ref": "#/$defs/vectorStoreSemantic"
          }
        }
      }
    },
    {
      "if": {
        "properties": {
          "kind": {
            "const": "MEMORY"
          }
        }
      },
      "then": {
        "properties": {
          "semantic": {
            "$ref": "#/$defs/memorySemantic"
          }
        }
      }
    },
    {
      "if": {
        "properties": {
          "kind": {
            "const": "GUARDRAIL"
          }
        }
      },
      "then": {
        "properties": {
          "semantic": {
            "$ref": "#/$defs/guardrailSemantic"
          }
        }
      }
    },
    {
      "if": {
        "properties": {
          "kind": {
            "const": "LOG"
          }
        }
      },
      "then": {
        "properties": {
          "semantic": {
            "$ref": "#/$defs/logSemantic"
          }
        }
      }
    }
  ],
  "$defs": {
    "traceId": {
      "type": "string",
      "pattern": "^[0-9a-f]{32}$"
    },
    "spanId": {
      "type": "string",
      "pattern": "^[0-9a-f]{16}$"
    },
    "uint64String": {
      "type": "string",
      "pattern": "^(0|[1-9][0-9]*)$"
    },
    "jsonValue": {
      "oneOf": [
        {
          "type": "null"
        },
        {
          "type": "boolean"
        },
        {
          "type": "number"
        },
        {
          "type": "string"
        },
        {
          "type": "array",
          "items": {
            "$ref": "#/$defs/jsonValue"
          }
        },
        {
          "type": "object",
          "additionalProperties": {
            "$ref": "#/$defs/jsonValue"
          }
        }
      ]
    },
    "spanKind": {
      "type": "string",
      "enum": [
        "WORKFLOW",
        "AGENT",
        "CHAIN",
        "TASK",
        "LLM",
        "TOOL",
        "MCP_TOOL",
        "RETRIEVER",
        "RERANKER",
        "EMBEDDING",
        "VECTOR_STORE",
        "MEMORY",
        "GUARDRAIL",
        "EVALUATOR",
        "LOG",
        "HTTP",
        "UNKNOWN"
      ]
    },
    "ownership": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "owner",
        "provider_generation",
        "project_key_id",
        "propagation"
      ],
      "properties": {
        "owner": {
          "type": "string",
          "enum": [
            "neatlogs-sdk",
            "neatlogs-ingest-adapter",
            "neatlogs-backend-recovery",
            "external-otel"
          ]
        },
        "provider_generation": {
          "type": "integer",
          "minimum": 0
        },
        "project_key_id": {
          "type": [
            "string",
            "null"
          ]
        },
